head.script:
//
window.dataLayer = window.dataLayer || [];
window.gtag = window.gtag || function(){window.dataLayer.push(arguments);};
window.gtag('consent', 'default', {
  'analytics_storage': 'denied',
  'ad_storage': 'denied',
  'ad_user_data': 'denied',
  'ad_personalization': 'denied',
  'wait_for_update': 500
});
window.gtag('set', 'ads_data_redaction', true);
//

//
(function(){
  var ID = 'G-95RKPEGCS9';
  window.rnUpdateAnalyticsConsent = function(accepted) {
    window.gtag('consent', 'update', { 'analytics_storage': accepted ? 'granted' : 'denied' });
  };
  // Blogger pode ter carregado a tag ou colocado a configuração na fila.
  var alreadyLoaded = !!document.querySelector('script[src*="googletagmanager.com/gtag/js"]');
  var alreadyConfigured = (window.dataLayer || []).some(function(item) {
    return item && item[0] === 'config' && item[1] === ID;
  });
  if (!alreadyLoaded && !alreadyConfigured) {
    var tag = document.createElement('script');
    tag.async = true;
    tag.src = 'https://www.googletagmanager.com/gtag/js?id=' + ID;
    document.head.appendChild(tag);
    window.gtag('js', new Date());
    window.gtag('config', ID);
  }
})();
//

body.script:
//
(function(){'use strict';
var open=document.getElementById('rn-us-open'),overlay=document.getElementById('rn-unified-search'),close=document.getElementById('rn-us-close'),input=document.getElementById('rn-us-query'),results=document.getElementById('rn-us-results'),status=document.getElementById('rn-us-status'),blogger=document.getElementById('rn-us-blogger');
var entries=[],loaded=false,loading=null,lastFocus=null;
function norm(v){return String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim()}
function strip(v){var el=document.createElement('div');el.innerHTML=String(v||'');return (el.textContent||'').replace(/\s+/g,' ').trim()}
function add(title,url,category,description){if(!title||!url)return;try{var u=new URL(url,location.origin);if(u.origin!==location.origin)return;var key=u.pathname.replace(/\/$/,'')||'/';var existing=entries.find(function(e){return e.key===key});if(existing){if(category!=='Página do site'){existing.title=String(title);existing.category=category||existing.category;existing.description=strip(description).slice(0,180)}return;}entries.push({title:String(title),url:u.href,key:key,category:category||'Página',description:strip(description).slice(0,180)})}catch(e){}}
function fromDOM(){document.querySelectorAll('a[href]').forEach(function(a){var href=a.getAttribute('href')||'',name=(a.textContent||'').trim();if(!name||name.length>120||href==='#'||href.startsWith('javascript:'))return;if(href.indexOf('/p/')!==-1||href.indexOf('/20')!==-1)add(name,a.href,'Página do site','')});document.querySelectorAll('#catalog-grid .service-row').forEach(function(card){var name=card.querySelector('strong');if(name)add(name.textContent,location.origin+'/#servicos','Serviço',card.textContent)});document.querySelectorAll('.guide-card a[href],.nav a[href]').forEach(function(a){add(a.textContent.trim()||a.getAttribute('aria-label'),a.href,'Guia ou ferramenta','')})}
function feed(path,category){return fetch(path,{credentials:'omit'}).then(function(r){if(!r.ok)throw Error('feed indisponível');return r.json()}).then(function(j){var list=(j.feed&&j.feed.entry)||[];list.forEach(function(e){var links=e.link||[],alt=links.find(function(l){return l.rel==='alternate'&&l.href});if(alt)add(e.title&&e.title.$t,alt.href,category,e.summary&&e.summary.$t||e.content&&e.content.$t||'')})})}
function load(){if(loaded)return Promise.resolve();if(loading)return loading;fromDOM();loading=Promise.allSettled([feed('/feeds/pages/default?alt=json&max-results=150','Página ou ferramenta'),feed('/feeds/posts/default?alt=json&max-results=150','Artigo ou guia')]).then(function(){loaded=true;loading=null;render()});return loading}
function render(){var q=norm(input.value),terms=q.split(/\s+/).filter(Boolean);blogger.href='/search?q='+encodeURIComponent(input.value.trim());results.replaceChildren();if(!q){status.textContent='Digite uma palavra para pesquisar.';return}var found=entries.map(function(e){var title=norm(e.title),all=norm(e.title+' '+e.description+' '+e.category),ok=terms.every(function(t){return all.includes(t)}),score=terms.reduce(function(n,t){return n+(title.includes(t)?5:0)+(norm(e.category).includes(t)?2:0)},0);return {e:e,ok:ok,score:score}}).filter(function(x){return x.ok}).sort(function(a,b){return b.score-a.score}).slice(0,30);status.textContent=found.length?found.length+' resultado(s) encontrado(s)'+(found.length===30?' (mostrando os primeiros 30)':''):'Nenhum resultado no índice local. Experimente a pesquisa completa do Blogger.';found.forEach(function(x){var li=document.createElement('li'),a=document.createElement('a'),small=document.createElement('small');a.href=x.e.url;a.textContent=x.e.title;small.textContent=x.e.category+(x.e.description?' — '+x.e.description:'');li.append(a,small);results.append(li)})}
var debounce;input.addEventListener('input',function(){clearTimeout(debounce);debounce=setTimeout(render,120)});
function show(){lastFocus=document.activeElement;overlay.hidden=false;document.body.classList.add('rn-search-open');input.focus();status.textContent='Carregando páginas, guias e serviços…';load().then(render)}function hide(){overlay.hidden=true;document.body.classList.remove('rn-search-open');if(lastFocus&&lastFocus.focus)lastFocus.focus()}
open.addEventListener('click',show);close.addEventListener('click',hide);overlay.addEventListener('click',function(e){if(e.target===overlay)hide()});document.addEventListener('keydown',function(e){if(overlay.hidden)return;if(e.key==='Escape')hide();if(e.key==='Tab'){var focusable=[input,blogger,close].concat(Array.from(results.querySelectorAll('a')));var i=focusable.indexOf(document.activeElement);if(e.shiftKey&&i===0){e.preventDefault();focusable[focusable.length-1].focus()}else if(!e.shiftKey&&i===focusable.length-1){e.preventDefault();focusable[0].focus()}}});
})();
//

//
(function(){
  if(location.pathname!=='/' && location.pathname!=='/index.html') return;
  function mount(){
    var home=document.getElementById('home-view');
    var vitrine=document.getElementById('rn-vitrine');
    if(!home || !vitrine || !document.body.classList.contains('rn-vitrine-home'))return true;
    // Reutiliza o mesmo botao de pesquisa, sem duplicar nem alterar os eventos originais.
    var searchButton=document.getElementById('rn-us-open');
    var navBrand=document.querySelector('#rn-vitrine .nav .brand');
    if(searchButton && navBrand && navBrand.parentNode){navBrand.parentNode.insertBefore(searchButton,navBrand.nextSibling);}

    try{(function(){
const items=[
['Impressões e xerox em papel ofício','Impressões','Documentos e trabalhos em preto e branco ou coloridos.'],['Impressões em papel fotográfico','Impressões','Fotos e imagens em papel fotográfico.'],['Impressões em papel adesivo','Impressões','Etiquetas, identificação e lembrancinhas.'],['Impressões em papel-cartão','Impressões','Convites, capas e materiais mais firmes.'],['Plastificação de documentos','Plastificação','Proteção e acabamento de documentos.'],['Plastificação de folhas A4 inteiras','Plastificação','Proteção para avisos e folhas A4.'],['Cartões de visita','Documentos','Cartões para profissionais e empresas.'],['Talões de recibos de aluguel','Documentos','Recibos organizados em talões.'],['Contratos de aluguel','Documentos','Impressão e preparação a partir das informações fornecidas.'],['Declarações de residência','Documentos','Preparação e impressão de declarações.'],['Cartazes A4','Comunicação','Cartazes para avisos e divulgação.'],['Banners','Comunicação','Banners em lona para eventos e comércios.'],['Agendamento no CRAS','Agendamentos','Apoio em consultas e agendamentos sujeitos a vagas.'],['Agendamento para identidade','Agendamentos','Apoio para agendar emissão de identidade.'],['Agendamento para título de eleitor','Agendamentos','Apoio para serviços de agendamento eleitoral.'],['Canecas personalizadas','Personalizados','Canecas com fotos, nomes e mensagens.'],['Camisas personalizadas','Personalizados','Camisas para equipes, eventos e presentes.'],['Estampas personalizadas','Personalizados','Estampas para camisetas e peças compatíveis.'],['Sublimação total','Personalizados','Personalização em peças compatíveis.'],['Estampas em DTF','Personalizados','Estampas detalhadas e coloridas em DTF.']
];
let selected='Todos';const grid=document.getElementById('serviceGrid');const search=document.getElementById('searchInput');const norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function render(){const q=norm(search.value.trim());const found=items.filter(x=>(selected==='Todos'||x[1]===selected)&&norm(x.join(' ')).includes(q));grid.replaceChildren();for(const x of found){const article=document.createElement('article');article.className='service';const tag=document.createElement('span');tag.className='tag';tag.textContent=x[1];const h=document.createElement('h3');h.textContent=x[0];const p=document.createElement('p');p.textContent=x[2];const btn=document.createElement('button');btn.className='more';btn.textContent='Pedir orçamento →';btn.addEventListener('click',()=>openQuote(x[0]));article.append(tag,h,p,btn);grid.append(article)}document.getElementById('empty').style.display=found.length?'none':'block';document.getElementById('resultCount').textContent=found.length+' de '+items.length+' serviços';document.querySelectorAll('[data-filter]').forEach(b=>{const active=b.dataset.filter===selected;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))})}
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{selected=b.dataset.filter;render()}));document.querySelectorAll('[data-category-link]').forEach(a=>a.addEventListener('click',()=>{selected=a.dataset.categoryLink;search.value='';render()}));search.addEventListener('input',render);document.getElementById('clearSearch').addEventListener('click',()=>{search.value='';selected='Todos';render();search.focus()});render();
const modal=document.getElementById('quoteModal');const first=document.getElementById('product');function openQuote(value){first.value=value||'Orçamento geral';modal.classList.add('open');document.body.style.overflow='hidden';first.focus()}function closeQuote(){modal.classList.remove('open');document.body.style.overflow=''}document.querySelectorAll('[data-rn-quote]').forEach(b=>b.addEventListener('click',()=>openQuote(b.dataset.rnQuote)));document.getElementById('closeModal').addEventListener('click',closeQuote);document.getElementById('cancelModal').addEventListener('click',closeQuote);modal.addEventListener('click',e=>{if(e.target===modal)closeQuote()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeQuote()});document.getElementById('quoteForm').addEventListener('submit',e=>{e.preventDefault();const p=first.value.trim(),n=document.getElementById('customer').value.trim(),q=document.getElementById('quantity').value.trim(),d=document.getElementById('details').value.trim();const msg=['Olá! Gostaria de solicitar um orçamento à R&N Gráfica Rápida.','Produto/serviço: '+p,n?'Nome: '+n:'',q?'Quantidade: '+q:'',d?'Detalhes: '+d:''].filter(Boolean).join('\n');window.open('https://wa.me/5581996090928?text='+encodeURIComponent(msg),'_blank','noopener');});
const hamburger=document.getElementById('hamb');const nav=document.getElementById('navLinks');hamburger.addEventListener('click',()=>{const open=nav.classList.toggle('open');hamburger.setAttribute('aria-expanded',String(open))});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');hamburger.setAttribute('aria-expanded','false')}));

})();}catch(e){console.error('R&N vitrine: erro na inicialização',e);}
    return true;
  }
  if(!mount()){
    var observer=new MutationObserver(function(){if(mount())observer.disconnect()});
    observer.observe(document.documentElement,{childList:true,subtree:true});
    document.addEventListener('DOMContentLoaded',function(){if(mount())observer.disconnect()});
  }
})();
//
